return [
  {
    json: {
      queries: ["yoga mat", "usb c cable"],
      max_results_per_query: 20,
      sort: "orders",
      ship_to: "US",
      currency: "USD"
    }
  }
];

const items = $input.all();
const qualified = [];

for (const item of items) {
  const p = item.json;
  if (!p || !p.product_id) continue;

  const price = p.price || 0;
  const origPrice = p.original_price || price;
  const discount = p.discount_percent || 0;
  const sold = p.sold || 0;
  const rating = p.rating || 0;
  const freeShip = p.shipping ? p.shipping.free_shipping : false;
  const delivery = p.shipping ? p.shipping.delivery_estimate : 'Standard';

  // Filter for proven sellers: discount >= 30% and sold >= 100
  if (discount >= 30 && sold >= 100) {
    qualified.push({
      json: {
        query: p.query,
        product_id: p.product_id,
        sku_id: p.sku_id,
        title: p.title,
        price_usd: price,
        original_price_usd: origPrice,
        discount_pct: discount,
        rating: rating,
        orders_sold: sold,
        free_shipping: freeShip,
        delivery_estimate: delivery,
        product_url: p.url,
        image_url: p.image_url,
        scraped_at: p.scraped_at
      }
    });
  }
}

return qualified;

const deals = $input.all();
return [{
  json: {
    status: "SUCCESS",
    message: `Discovered ${deals.length} high-margin AliExpress products with verified supplier ratings and discounts.`,
    top_deals: deals.slice(0, 5).map(d => ({
      title: d.json.title,
      price: `$${d.json.price_usd} (was $${d.json.original_price_usd})`,
      discount: `${d.json.discount_pct}% OFF`,
      orders: d.json.orders_sold,
      rating: d.json.rating,
      url: d.json.product_url
    }))
  }
}];
